head.b:skin:
/* 
THEME: Nahwu Academic Framework (Emerald & Gold Edition)
SYSTEM: Arabic Grammar Engine
*/
:root {
    --emerald: #065f46;
    --gold: #fbbf24;
    --dark-arabic: #064e3b;
    --card-bg: #ffffff;
    --text-main: #1f2937;
}
body {
    background-color: #f3f4f6;
    color: var(--text-main);
    font-family: 'Inter', 'Noto Sans Arabic', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--emerald), var(--dark-arabic));
    color: var(--gold);
    padding: 50px 20px;
    text-align: center;
    border-bottom: 4px solid var(--gold);
}
.main-container {
    max-width: 900px;
    margin: -30px auto 50px;
    padding: 20px;
}
.academic-card {
    background: var(--card-bg);
    border-radius: 15px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.1);
    padding: 30px;
    margin-bottom: 25px;
    border-top: 5px solid var(--emerald);
}
.input-group { margin-bottom: 20px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--emerald);
    font-size: 14px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 12px;
    border: 1px solid #d1d5db;
    border-radius: 8px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fff;
}
.input-group textarea { height: 120px; resize: vertical; }

.lang-options { display: flex; gap: 20px; margin-top: 5px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 500; }
.lang-item input { width: auto; margin-right: 8px; }

h2 { color: var(--emerald); border-bottom: 2px solid #f3f4f6; padding-bottom: 10px; margin-top: 0; }

.copy-btn {
    background: var(--emerald);
    color: #fff;
    border: none;
    padding: 15px 20px;
    cursor: pointer;
    font-weight: bold;
    border-radius: 8px;
    width: 100%;
    transition: 0.3s;
    font-size: 16px;
    text-transform: uppercase;
}
.copy-btn:hover { background: var(--dark-arabic); box-shadow: 0 4px 12px rgba(6, 95, 70, 0.3); }
footer { text-align: center; color: #6b7280; padding: 20px; font-size: 12px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "[Belum ditentukan]";
    var notes = document.getElementById("inputNotes").value || "[Tidak ada catatan]";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateAR").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("Prompt Nahwu (" + (selectedLang === 'id' ? 'Bahasa Indonesia' : 'العربية') + ") berhasil disalin!");
}
